import{_ as o,C as e,o as n,c as d,j as a,a as l,E as s,a3 as i}from"./chunks/framework.CZBGEXos.js";const q=JSON.parse('{"title":"Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/analyzer.md","filePath":"ru/tools/analyzer.md"}'),h={name:"ru/tools/analyzer.md"};function c(g,t,p,u,b,m){const r=e("Screenshot");return n(),d("div",null,[t[0]||(t[0]=a("h1",{id:"analyzer",tabindex:"-1"},[l("Analyzer "),a("a",{class:"header-anchor",href:"#analyzer","aria-label":'Permalink to "Analyzer"'},"​")],-1)),t[1]||(t[1]=a("p",null,"Analyzer — это рабочее пространство для графиков: один тикер, несколько таймфреймов рядом, на выбранной вами бирже. Это единственный инструмент, где можно рисовать на графиках.",-1)),s(r,{src:"analyzer",alt:"Окно Analyzer с четырьмя графиками, списком тикеров и списком наблюдения",caption:"Окно Analyzer"}),t[2]||(t[2]=i('<p>В отличие от других инструментов, Analyzer почти ничего не настраивает в главном окне — всё управляется из самого окна, а ваша раскладка запоминается между сеансами.</p><h2 id="раскладка" tabindex="-1">Раскладка <a class="header-anchor" href="#раскладка" aria-label="Permalink to &quot;Раскладка&quot;">​</a></h2><p>Окно состоит из двух частей: панели списков с <strong>Markets</strong> и вашими <strong>списками наблюдения</strong>, и область графиков. Панели можно перетаскивать и стыковать; раскладка запоминается.</p><h2 id="что-выводить-на-график" tabindex="-1">Что выводить на график <a class="header-anchor" href="#что-выводить-на-график" aria-label="Permalink to &quot;Что выводить на график&quot;">​</a></h2><h3 id="биржа" tabindex="-1">Биржа <a class="header-anchor" href="#биржа" aria-label="Permalink to &quot;Биржа&quot;">​</a></h3><p>Пять кнопок бирж: <strong>Bybit</strong>, <strong>Binance</strong>, <strong>Gate</strong> (Gate.io), <strong>OKX</strong> и <strong>Hyper</strong> (Hyperliquid). Переключение биржи перезагружает список тикеров и переводит все графики на новую биржу без перезагрузки окна.</p><p>Рисунки хранятся для каждого символа <em>и</em> для каждой биржи, так что у одного и того же тикера на двух биржах два отдельных набора рисунков.</p><h3 id="тип-рынка" tabindex="-1">Тип рынка <a class="header-anchor" href="#тип-рынка" aria-label="Permalink to &quot;Тип рынка&quot;">​</a></h3><p><strong>FUT</strong> (бессрочные фьючерсы) или <strong>SPOT</strong>. Это меняет, какие рынки показаны и какие метрики существуют — см. <a href="#колонки-метрик">Колонки метрик</a>.</p><p>Переключение на SPOT сбрасывает активную метрику на 24H%, потому что у спотовых рынков нет открытого интереса, ставки финансирования и NATR.</p><h3 id="поиск" tabindex="-1">Поиск <a class="header-anchor" href="#поиск" aria-label="Permalink to &quot;Поиск&quot;">​</a></h3><p>Поле поиска фильтрует список тикеров и намеренно снисходительно:</p><ul><li>Знаки препинания, пробелы, дефисы и слэши игнорируются.</li><li>Запросы от трёх символов выдерживают пропущенную или ошибочно набранную букву.</li><li><strong>Кириллица транслитерируется по расположению клавиш.</strong> Набрав <code>ИЕСГЫВЕ</code> в русской раскладке, вы найдёте <code>BTCUSDT</code>, потому что это те же физические клавиши. Переключать раскладку для поиска не нужно.</li></ul><h3 id="колонки-метрик" tabindex="-1">Колонки метрик <a class="header-anchor" href="#колонки-метрик" aria-label="Permalink to &quot;Колонки метрик&quot;">​</a></h3><p>Список показывает колонку символа плюс одну или несколько колонок метрик:</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Значение</th><th>Рынки</th></tr></thead><tbody><tr><td><strong>24H%</strong></td><td>Изменение цены за 24 часа</td><td>Фьючерсы и спот</td></tr><tr><td><strong>VOL</strong></td><td>Объём торгов за 24 часа в долларах</td><td>Фьючерсы и спот</td></tr><tr><td><strong>OI</strong></td><td>Открытый интерес — суммарные открытые позиции в долларах</td><td>Только фьючерсы</td></tr><tr><td><strong>FR</strong></td><td>Ставка финансирования</td><td>Только фьючерсы</td></tr><tr><td><strong>NATR</strong></td><td>Волатильность — ATR(14) на 5м свечах ÷ цена, в %</td><td>Только фьючерсы</td></tr></tbody></table><p>Нажмите на заголовок колонки, чтобы отсортировать по ней; нажмите ещё раз, чтобы сменить направление. Активная сортировка отмечена стрелкой. Заголовок <strong>SYMBOL</strong> сортирует по названию тикера: A→Z, Z→A, затем выключено.</p><p><strong>Сортировка по NATR</strong> — самый быстрый способ найти, что сейчас волатильно на бирже, которую вы смотрите. Это та же мера, по которой ранжирует <a href="/manual/ru/tools/monitor.html">Monitor</a>, обновляется каждые 10 секунд. <strong>Приглушенное</strong> значение NATR означает, что у тикера меньше 14 закрытых 5м свечей — обычно это свежий листинг, — так что цифра ещё шумная.</p><p>Если биржа совсем не сообщает какую-то метрику, её колонка убирается, вместо того чтобы показывать столбец <code>-</code>. У Binance, Gate.io и OKX нет колонки OI; у Binance и OKX нет колонки FR.</p><p>Сколько колонок видно, <strong>зависит от ширины панели</strong>. Сузьте панель — и останется только активная метрика; расширьте — и колонки будут возвращаться по одной. Markets и списки наблюдения измеряются отдельно, так что одновременно могут показывать разное количество колонок.</p><h3 id="списки-наблюдения" tabindex="-1">Списки наблюдения <a class="header-anchor" href="#списки-наблюдения" aria-label="Permalink to &quot;Списки наблюдения&quot;">​</a></h3><p>Можно держать <strong>сколько угодно именованных списков наблюдения</strong>. Каждый — отдельная панель с вкладкой и собственным цветом.</p><ul><li><strong>Добавить тикер</strong> — нажмите закладку в конце его строки в Markets. Если список один, это сразу добавляет или убирает тикер. Если их несколько, открывается меню, где вы отмечаете нужные списки. Тикер может быть в нескольких списках одновременно.</li><li><strong>Где он есть</strong> — цветные метки-закладки рядом с тикером показывают, какие списки его содержат. Наведите, чтобы увидеть названия.</li><li><strong>Убрать тикер</strong> — <strong>×</strong> в его строке в списке наблюдения.</li><li><strong>Новый список</strong> — <strong>+</strong> рядом с вкладками списков. Новый список открывается вкладкой в этой группе, с названием, готовым к редактированию.</li><li><strong>Переименовать</strong> — двойной клик по вкладке.</li><li><strong>Удалить</strong> — <strong>×</strong> на вкладке. Если в списке ещё есть тикеры, первый клик «взводит» удаление (<code>delete?</code>), а второй клик в течение 3 секунд удаляет. Один список есть всегда.</li></ul><p>Перетащите вкладку списка, чтобы пристыковать его в другом месте: рядом с Markets, под ним или отдельной колонкой.</p><p>Каждая запись показывает логотипы бирж, где она торгуется — при наведении видно <code>Listed on &lt;биржа&gt;</code>. Значки листинга соответствуют <strong>текущему типу рынка</strong>: токен, который торгуется только на споте, не получит значка, пока вы во фьючерсах.</p><p>Списки сохраняются между сеансами. Единственный список из более старой версии сохраняется как первый, с названием <strong>Watchlist</strong>.</p><h2 id="графики" tabindex="-1">Графики <a class="header-anchor" href="#графики" aria-label="Permalink to &quot;Графики&quot;">​</a></h2><h3 id="панели" tabindex="-1">Панели <a class="header-anchor" href="#панели" aria-label="Permalink to &quot;Панели&quot;">​</a></h3><p>Analyzer открывается с четырьмя панелями графиков на <strong>5м, 15м, 1ч и 4ч</strong>. Это отправная точка, а не фиксированная раскладка:</p><ul><li><strong>Add chart</strong> добавляет панель, максимум до <strong>8</strong>.</li><li><strong>Close chart</strong> убирает одну, минимум до <strong>1</strong>.</li><li>У каждой панели свой выпадающий список таймфреймов: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>.</li></ul><p>Ваша раскладка панелей и таймфрейм каждой из них сохраняются, так что окно возвращается таким, каким вы его оставили.</p><h3 id="история" tabindex="-1">История <a class="header-anchor" href="#история" aria-label="Permalink to &quot;История&quot;">​</a></h3><p>Прокручивайте график влево, чтобы автоматически подгружать более старые свечи партиями — настолько далеко, насколько их отдаёт биржа.</p><h3 id="гистограмма-объема" tabindex="-1">Гистограмма объёма <a class="header-anchor" href="#гистограмма-объема" aria-label="Permalink to &quot;Гистограмма объёма&quot;">​</a></h3><p>Кнопка <strong>Vol</strong> в заголовке (рядом с <strong>+ Chart</strong>) включает или выключает <a href="/manual/ru/customize/chart-colors.html#гистограмма-объема">гистограмму объёма</a> на всех панелях графиков. Клавиша <kbd>V</kbd> делает то же самое.</p><h3 id="полныи-экран" tabindex="-1">Полный экран <a class="header-anchor" href="#полныи-экран" aria-label="Permalink to &quot;Полный экран&quot;">​</a></h3><p>У каждой панели есть кнопка разворота на весь экран. В полноэкранном режиме рядом с каждым таймфреймом в списке появляется звёздочка — отмеченные таймфреймы показываются строкой быстрого доступа, общей с полноэкранными видами Knives и Monitor.</p><p>Чтобы выйти, нажмите <kbd>Esc</kbd> или кнопку закрытия.</p><h3 id="инструменты-рисования" tabindex="-1">Инструменты рисования <a class="header-anchor" href="#инструменты-рисования" aria-label="Permalink to &quot;Инструменты рисования&quot;">​</a></h3><p>На каждом графике доступны пять инструментов, каждый на своей клавише:</p><table tabindex="0"><thead><tr><th>Инструмент</th><th>Клавиша по умолчанию</th></tr></thead><tbody><tr><td>Горизонтальный луч</td><td><kbd>H</kbd></td></tr><tr><td>Трендовая линия</td><td><kbd>T</kbd></td></tr><tr><td>Прямоугольник</td><td><kbd>B</kbd></td></tr><tr><td>Карандаш</td><td><kbd>P</kbd></td></tr><tr><td>Исчезающий карандаш</td><td><kbd>F</kbd></td></tr></tbody></table><p>Удерживайте <kbd>Ctrl</kbd> при постановке точки, чтобы привязать её к ближайшему максимуму или минимуму свечи.</p><p>Активный инструмент отслеживается <strong>для каждой панели отдельно</strong>, так что можно рисовать трендовую линию на одной панели, пока другая остаётся без инструмента.</p><p>Клавиши, цвет рисунков и поведение магнита настраиваются — см. <a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a>.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>У вкладки <strong>Analyzer</strong> в главном окне нет настроек. В ней только кнопка <strong>Open Window</strong> и раздел заметок.</p><h3 id="известные-проблемы" tabindex="-1">Известные проблемы <a class="header-anchor" href="#известные-проблемы" aria-label="Permalink to &quot;Известные проблемы&quot;">​</a></h3><p>Вкладка сообщает об одном известном ограничении, цитата из приложения:</p><blockquote><p>Графики Gate.io загружаются дольше, чем на других биржах. Это известная проблема, над исправлением ведётся работа.</p></blockquote><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a> — цвета свечей, цвет рисунков, клавиши инструментов, магнит</li><li><a href="/manual/ru/tools/monitor.html">Monitor</a> — ранжированный сканер; его карточки тоже открывают полноэкранные графики с теми же инструментами рисования</li><li><a href="/manual/ru/customize/majors.html">Слой мажоров</a> — крупные сделки, кластеры объёма и ликвидации на любой панели</li></ul>',51))])}const f=o(h,[["render",c]]);export{q as __pageData,f as default};
